#include <stdio.h>
#include <stdlib.h>

typedef struct {
    long long d2;
    int u;
    int v;
} Edge;

typedef struct {
    int node;
    int val;
} Update;

int cmp_edges(const void *a, const void *b) {
    long long d1 = ((const Edge *)a)->d2;
    long long d2 = ((const Edge *)b)->d2;
    if (d1 < d2) return -1;
    if (d1 > d2) return 1;
    return 0;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    long long *x = (long long *)malloc((n + 1) * sizeof(long long));
    long long *y = (long long *)malloc((n + 1) * sizeof(long long));

    x[0] = 0;
    y[0] = 0;
    for (int i = 1; i <= n; i++) {
        scanf("%lld %lld", &x[i], &y[i]);
    }

    int total_edges = n + n * (n - 1) / 2;
    Edge *edges = (Edge *)malloc(total_edges * sizeof(Edge));

    int edge_count = 0;
    for (int i = 1; i <= n; i++) {
        long long dx = x[i] - x[0];
        long long dy = y[i] - y[0];
        edges[edge_count].d2 = dx * dx + dy * dy;
        edges[edge_count].u = 0;
        edges[edge_count].v = i;
        edge_count++;
    }

    for (int i = 1; i <= n; i++) {
        for (int j = i + 1; j <= n; j++) {
            long long dx = x[i] - x[j];
            long long dy = y[i] - y[j];
            edges[edge_count].d2 = dx * dx + dy * dy;
            edges[edge_count].u = i;
            edges[edge_count].v = j;
            edge_count++;
        }
    }

    qsort(edges, edge_count, sizeof(Edge), cmp_edges);

    int *dp = (int *)calloc(n + 1, sizeof(int));
    Update *updates = (Update *)malloc(2 * (total_edges + 1) * sizeof(Update));

    int ans = 0;
    int i = 0;
    while (i < edge_count) {
        int j = i;
        while (j < edge_count && edges[j].d2 == edges[i].d2) {
            j++;
        }

        int up_count = 0;
        for (int k = i; k < j; k++) {
            int u = edges[k].u;
            int v = edges[k].v;

            if (u == 0) {
                if (1 + dp[v] > ans) {
                    ans = 1 + dp[v];
                }
            } else {
                updates[up_count].node = u;
                updates[up_count].val = 1 + dp[v];
                up_count++;

                updates[up_count].node = v;
                updates[up_count].val = 1 + dp[u];
                up_count++;
            }
        }

        for (int k = 0; k < up_count; k++) {
            int node = updates[k].node;
            int val = updates[k].val;
            if (val > dp[node]) {
                dp[node] = val;
            }
        }

        i = j;
    }

    printf("%d\n", ans);

    free(x);
    free(y);
    free(edges);
    free(dp);
    free(updates);

    return 0;
}
